cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier reduction at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: S1-S4 (AC-1..AC-4), values copied from ac.md.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so
  # no scenario exists for it and none may be invented. Escalated to DISCUSS.

  @happy-path @smoke
  Scenario: S1 Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: S2 Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: S3 Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: S4 Bronze customer's reduction lands on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/CalculateLoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int Charged(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // S1 Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeTenThousandIsChargedNineThousandFiveHundred() =>
        Assert.Equal(9500, Charged(10000, LoyaltyTier.Bronze));

    // S2 Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverTenThousandIsChargedNineThousand() =>
        Assert.Equal(9000, Charged(10000, LoyaltyTier.Silver));

    // S3 Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldTenThousandIsChargedEightThousandFiveHundred() =>
        Assert.Equal(8500, Charged(10000, LoyaltyTier.Gold));

    // S4 Bronze customer's reduction lands on a whole cent in their favour
    [Fact]
    public void S4_BronzeSevenCentsIsChargedSevenCents() =>
        Assert.Equal(7, Charged(7, LoyaltyTier.Bronze));
}
EOF
cd tests/CheckoutPricing.UnitTest && dotnet test 2>&1 | grep -E "Failed |Expected|Actual|Passed!|Failed!|error" | head -30

